SELECT '==ASSIGN 606 (MODULO INFORMATICA) ?EN SECCION 924?==' as '';
SELECT cm.id, cm.section, s.name FROM isi_course_modules cm JOIN isi_course_sections s ON s.id = cm.section WHERE cm.instance = 606;
SELECT '==ASSIGN 736 (PARA BUZOS) ?EN SECCION 924?==' as '';
SELECT cm.id, cm.section, s.name FROM isi_course_modules cm JOIN isi_course_sections s ON s.id = cm.section WHERE cm.instance = 736;
SELECT '==?QUE SECTION PERTENECE LA ASSIGN 544 ORIGINALMENTE?==' as '';
SELECT id, eventname, from_unixtime(timecreated) dt, other FROM isi_logstore_standard_log WHERE eventname = '\\core\\event\\course_module_created' AND contextinstanceid IN (SELECT id FROM isi_course_modules WHERE instance = 544) LIMIT 5;
SELECT '==SECTION DE CM 9916 (ASSIGN 544 DELETED)==' as '';
SELECT id, course, section, instance FROM isi_course_modules WHERE id = 9916;
SELECT '==SECTION DE CM 10451 (ASSIGN 735 DELETED)==' as '';
SELECT id, course, section, instance FROM isi_course_modules WHERE id = 10451;
SELECT '==?SUBMISSION ACTIVA DE SOLANGEL (USER 2758) PARA ASSIGN 606 O 736?==' as '';
SELECT s.id, s.assignment, s.userid, s.status, from_unixtime(s.timecreated) tc FROM isi_assign_submission s WHERE s.userid = 2758 AND s.assignment IN (606, 736) AND s.latest = 1;
SELECT '==GRADE_GRADES PARA SOLANGEL EN ITEMS 2877 (assign 606), 3095 (assign 736)==' as '';
SELECT gi.id, gi.itemname, gi.iteminstance, gg.finalgrade, gg.rawgrade FROM isi_grade_items gi LEFT JOIN isi_grade_grades gg ON gg.itemid = gi.id AND gg.userid = 2758 WHERE gi.iteminstance IN (606, 736) AND gi.courseid = 74;
SELECT '==HISTORIAL DE GRADES PARA SOLANGEL EN ITEMS RELACIONADOS A MODULO==' as '';
SELECT t.itemid, t.finalgrade, t.dt FROM (SELECT gh.itemid, gh.userid, gh.finalgrade, from_unixtime(gh.timemodified) dt, ROW_NUMBER() OVER (PARTITION BY gh.itemid, gh.userid ORDER BY gh.timemodified DESC) AS rn FROM isi_grade_grades_history gh WHERE gh.userid = 2758 AND gh.itemid IN (2785, 3094) AND gh.finalgrade IS NOT NULL AND gh.finalgrade >= 0) t WHERE t.rn = 1;
